def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re
    import sys

    token_re = re.compile(r"\s*(\d+|[A-Z]+[1-9]\d?|[A-Z]+|<>|<=|>=|[+\-*/(),:=<>])")

    def parse(text):
        tokens = token_re.findall(text)
        pos = 0

        def expression(min_precedence=0):
            nonlocal pos

            if tokens[pos] == "-":
                pos += 1
                node = ("neg", expression(3))
            elif tokens[pos] == "(":
                pos += 1
                node = expression()
                pos += 1
            elif tokens[pos].isdigit():
                node = ("num", int(tokens[pos]))
                pos += 1
            elif tokens[pos] in ("SUM", "MIN", "MAX"):
                name = tokens[pos]
                pos += 2
                args = []
                while True:
                    if (
                        pos + 1 < len(tokens)
                        and re.fullmatch(r"[A-Z][1-9]\d?", tokens[pos])
                        and tokens[pos + 1] == ":"
                    ):
                        args.append(("range", tokens[pos], tokens[pos + 2]))
                        pos += 3
                    else:
                        args.append(expression())
                    if tokens[pos] != ",":
                        break
                    pos += 1
                pos += 1
                node = ("func", name, args)
            elif tokens[pos] == "IF":
                pos += 2
                left = expression()
                op = tokens[pos]
                pos += 1
                right = expression()
                pos += 1
                then = expression()
                pos += 1
                otherwise = expression()
                pos += 1
                node = ("if", op, left, right, then, otherwise)
            else:
                node = ("ref", tokens[pos])
                pos += 1

            precedence = {"+": 1, "-": 1, "*": 2, "/": 2}
            while pos < len(tokens):
                op = tokens[pos]
                priority = precedence.get(op, 0)
                if priority <= min_precedence:
                    break
                pos += 1
                right = expression(priority)
                node = ("bin", op, node, right)
            return node

        return expression()

    parsed = {}
    values = {}
    active = set()

    def eval_cell(name):
        if name not in cells:
            return 0
        if name in values:
            return values[name]
        if name in active:
            return "#CYCLE!"

        active.add(name)
        content = cells[name]
        if content.startswith("="):
            if name not in parsed:
                parsed[name] = parse(content[1:])
            value = evaluate(parsed[name])
        else:
            value = int(content)
        active.remove(name)
        values[name] = value
        return value

    def evaluate(node):
        kind = node[0]

        if kind == "num":
            return node[1]
        if kind == "ref":
            return eval_cell(node[1])
        if kind == "neg":
            value = evaluate(node[1])
            return value if isinstance(value, str) else -value
        if kind == "bin":
            left = evaluate(node[2])
            if isinstance(left, str):
                return left
            right = evaluate(node[3])
            if isinstance(right, str):
                return right
            op = node[1]
            if op == "+":
                return left + right
            if op == "-":
                return left - right
            if op == "*":
                return left * right
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient

        if kind == "if":
            left = evaluate(node[2])
            if isinstance(left, str):
                return left
            right = evaluate(node[3])
            if isinstance(right, str):
                return right
            op = node[1]
            if op == "=":
                condition = left == right
            elif op == "<>":
                condition = left != right
            elif op == "<":
                condition = left < right
            elif op == "<=":
                condition = left <= right
            elif op == ">":
                condition = left > right
            else:
                condition = left >= right
            return evaluate(node[4] if condition else node[5])

        name, args = node[1], node[2]
        result = None
        for arg in args:
            if arg[0] == "range":
                start, end = arg[1], arg[2]
                col1, col2 = sorted((ord(start[0]), ord(end[0])))
                row1, row2 = sorted((int(start[1:]), int(end[1:])))
                items = (
                    chr(col) + str(row)
                    for row in range(row1, row2 + 1)
                    for col in range(col1, col2 + 1)
                    if chr(col) + str(row) in cells
                )
                for cell in items:
                    value = eval_cell(cell)
                    if isinstance(value, str):
                        return value
                    if result is None:
                        result = value
                    elif name == "SUM":
                        result += value
                    elif name == "MIN":
                        result = min(result, value)
                    else:
                        result = max(result, value)
            else:
                value = evaluate(arg)
                if isinstance(value, str):
                    return value
                if result is None:
                    result = value
                elif name == "SUM":
                    result += value
                elif name == "MIN":
                    result = min(result, value)
                else:
                    result = max(result, value)
        return 0 if result is None else result

    previous_limit = sys.getrecursionlimit()
    sys.setrecursionlimit(max(previous_limit, 1000000))
    try:
        return {name: eval_cell(name) for name in cells}
    finally:
        sys.setrecursionlimit(previous_limit)
